WHERE n.nspname IN ('public', 'storage', 'auth', 'extensions', 'graphql_public', 'supabase_migrations')
ORDER BY n.nspname, c.relname, tn.nspname NULLS FIRST, tc.relname NULLS FIRST, a.attname NULLS FIRST) AS source_row WHERE source_row."sequence_schema" = 'public') AS actual_row;
  IF EXISTS (
