-- dealflow:gate-group public.10a_routines.function_procedure_window_definitions
DO $dealflow_catalog_gate_13$
DECLARE
  expected jsonb := $dealflow_expected_13$[{"definition_bytes":1814,"full_arguments":"p_bucket_key text, p_max_requests integer, p_window_ms integer","identity_arguments":"p_bucket_key text, p_max_requests integer, p_window_ms integer","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.consume_rate_limit_bucket(p_bucket_key text, p_max_requests integer, p_window_ms integer)\n RETURNS TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  bucket public.rate_limit_buckets%rowtype;\n  now_at timestamptz := now();\n  next_reset timestamptz := now() + (greatest(p_window_ms, 1000)::text || ' milliseconds')::interval;\nbegin\n  if p_bucket_key is null or length(trim(p_bucket_key)) = 0 then\n    raise exception 'bucket_key is required';\n  end if;\n\n  if p_max_requests <= 0 then\n    raise exception 'max_requests must be positive';\n  end if;\n\n  insert into public.rate_limit_buckets (bucket_key, request_count, reset_at)\n  values (p_bucket_key, 0, next_reset)\n  on conflict (bucket_key) do nothing;\n\n  select *\n  into bucket\n  from public.rate_limit_buckets\n  where rate_limit_buckets.bucket_key = p_bucket_key\n  for update;\n\n  if bucket.reset_at <= now_at then\n    update public.rate_limit_buckets\n    set request_count = 1,\n        reset_at = next_reset,\n        updated_at = now_at\n    where rate_limit_buckets.bucket_key = p_bucket_key;\n\n    allowed := true;\n    remaining := greatest(p_max_requests - 1, 0);\n    reset_at := next_reset;\n    return next;\n    return;\n  end if;\n\n  if bucket.request_count >= p_max_requests then\n    allowed := false;\n    remaining := 0;\n    reset_at := bucket.reset_at;\n    return next;\n    return;\n  end if;\n\n  update public.rate_limit_buckets\n  set request_count = bucket.request_count + 1,\n      updated_at = now_at\n  where rate_limit_buckets.bucket_key = p_bucket_key;\n\n  allowed := true;\n  remaining := greatest(p_max_requests - bucket.request_count - 1, 0);\n  reset_at := bucket.reset_at;\n  return next;\nend;\n$function$\n","routine_kind":"f","routine_name":"consume_rate_limit_bucket","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":1985,"full_arguments":"p_worker_id text, p_lease_ms integer DEFAULT 300000","identity_arguments":"p_worker_id text, p_lease_ms integer","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"SETOF system_jobs","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.claim_next_system_job(p_worker_id text, p_lease_ms integer DEFAULT 300000)\n RETURNS SETOF system_jobs\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  claimed_id uuid;\nbegin\n  if p_worker_id is null or length(trim(p_worker_id)) = 0 then\n    raise exception 'p_worker_id is required';\n  end if;\n\n  update public.system_jobs\n  set status = 'failed',\n      dead_lettered_at = coalesce(dead_lettered_at, now()),\n      dead_letter_reason = coalesce(dead_letter_reason, 'Maximum job attempts reached before claim.'),\n      locked_by = null,\n      locked_until = null,\n      completed_at = coalesce(completed_at, now()),\n      error_message = coalesce(error_message, 'Maximum job attempts reached before claim.')\n  where dead_lettered_at is null\n    and status in ('pending', 'processing')\n    and attempt_count >= max_attempts\n    and (\n      status = 'pending'\n      or locked_until is null\n      or locked_until <= now()\n    );\n\n  with candidate as (\n    select id\n    from public.system_jobs\n    where (\n        status = 'pending'\n        or (\n          status = 'processing'\n          and locked_until is not null\n          and locked_until <= now()\n        )\n      )\n      and (next_run_at is null or next_run_at <= now())\n      and dead_lettered_at is null\n      and attempt_count < max_attempts\n    order by created_at asc\n    for update skip locked\n    limit 1\n  )\n  update public.system_jobs\n  set status = 'processing',\n      locked_by = p_worker_id,\n      locked_until = now() + (greatest(p_lease_ms, 1000)::text || ' milliseconds')::interval,\n      started_at = coalesce(started_at, now()),\n      completed_at = null,\n      error_message = null,\n      attempt_count = attempt_count + 1\n  where id in (select id from candidate)\n  returning id into claimed_id;\n\n  if claimed_id is null then\n    return;\n  end if;\n\n  return query\n  select *\n  from public.system_jobs\n  where id = claimed_id;\nend;\n$function$\n","routine_kind":"f","routine_name":"claim_next_system_job","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":222,"full_arguments":"","identity_arguments":"","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"trigger","returns_set":false,"routine_definition":"CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nbegin\n  new.updated_at = timezone('utc', now());\n  return new;\nend;\n$function$\n","routine_kind":"f","routine_name":"set_updated_at","routine_schema":"public","security_definer":false,"strict":false,"volatility":"v"},{"definition_bytes":2289,"full_arguments":"p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb","identity_arguments":"p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text, p_reference_id text, p_idempotency_key text, p_metadata jsonb","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"TABLE(balance integer, ledger_id uuid, reused_existing boolean)","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.grant_user_credits(p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS TABLE(balance integer, ledger_id uuid, reused_existing boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  current_balance integer;\n  next_balance integer;\n  existing_ledger public.user_credit_ledger%rowtype;\n  inserted_ledger public.user_credit_ledger%rowtype;\nbegin\n  if p_user_id is null then\n    raise exception 'user_id is required';\n  end if;\n\n  if p_amount is null or p_amount <= 0 then\n    raise exception 'credit amount must be positive';\n  end if;\n\n  if p_reason is null or length(trim(p_reason)) = 0 then\n    raise exception 'credit reason is required';\n  end if;\n\n  if p_idempotency_key is not null then\n    select *\n      into existing_ledger\n      from public.user_credit_ledger\n     where idempotency_key = p_idempotency_key\n       and user_id = p_user_id\n     limit 1;\n\n    if found then\n      return query select existing_ledger.balance_after, existing_ledger.id, true;\n      return;\n    end if;\n  end if;\n\n  insert into public.user_credits (user_id, balance)\n  values (p_user_id, 0)\n  on conflict (user_id) do nothing;\n\n  select uc.balance\n    into current_balance\n    from public.user_credits uc\n   where uc.user_id = p_user_id\n   for update;\n\n  next_balance := current_balance + p_amount;\n\n  update public.user_credits\n     set balance = next_balance,\n         updated_at = now()\n   where user_id = p_user_id;\n\n  insert into public.user_credit_ledger (\n    user_id,\n    organization_id,\n    delta,\n    balance_after,\n    reason,\n    reference_type,\n    reference_id,\n    idempotency_key,\n    metadata\n  )\n  values (\n    p_user_id,\n    p_organization_id,\n    p_amount,\n    next_balance,\n    trim(p_reason),\n    nullif(trim(coalesce(p_reference_type, '')), ''),\n    nullif(trim(coalesce(p_reference_id, '')), ''),\n    nullif(trim(coalesce(p_idempotency_key, '')), ''),\n    coalesce(p_metadata, '{}'::jsonb)\n  )\n  returning * into inserted_ledger;\n\n  return query select next_balance, inserted_ledger.id, false;\nend;\n$function$\n","routine_kind":"f","routine_name":"grant_user_credits","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":2613,"full_arguments":"p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb","identity_arguments":"p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text, p_reference_id text, p_idempotency_key text, p_metadata jsonb","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"TABLE(allowed boolean, balance integer, ledger_id uuid, reused_existing boolean)","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.consume_user_credits(p_user_id uuid, p_organization_id uuid, p_amount integer, p_reason text, p_reference_type text DEFAULT NULL::text, p_reference_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS TABLE(allowed boolean, balance integer, ledger_id uuid, reused_existing boolean)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  current_balance integer;\n  next_balance integer;\n  overdraft_limit integer := 2000;\n  existing_ledger public.user_credit_ledger%rowtype;\n  inserted_ledger public.user_credit_ledger%rowtype;\nbegin\n  if p_user_id is null then\n    raise exception 'user_id is required';\n  end if;\n\n  if p_amount is null or p_amount <= 0 then\n    raise exception 'credit amount must be positive';\n  end if;\n\n  if p_reason is null or length(trim(p_reason)) = 0 then\n    raise exception 'credit reason is required';\n  end if;\n\n  if p_idempotency_key is not null then\n    select *\n      into existing_ledger\n      from public.user_credit_ledger\n     where idempotency_key = p_idempotency_key\n       and user_id = p_user_id\n     limit 1;\n\n    if found then\n      return query select true, existing_ledger.balance_after, existing_ledger.id, true;\n      return;\n    end if;\n  end if;\n\n  insert into public.user_credits (user_id, balance)\n  values (p_user_id, 0)\n  on conflict (user_id) do nothing;\n\n  select uc.balance\n    into current_balance\n    from public.user_credits uc\n   where uc.user_id = p_user_id\n   for update;\n\n  next_balance := current_balance - p_amount;\n\n  if next_balance < -overdraft_limit then\n    return query select false, current_balance, null::uuid, false;\n    return;\n  end if;\n\n  update public.user_credits\n     set balance = next_balance,\n         updated_at = now()\n   where user_id = p_user_id;\n\n  insert into public.user_credit_ledger (\n    user_id,\n    organization_id,\n    delta,\n    balance_after,\n    reason,\n    reference_type,\n    reference_id,\n    idempotency_key,\n    metadata\n  )\n  values (\n    p_user_id,\n    p_organization_id,\n    -p_amount,\n    next_balance,\n    trim(p_reason),\n    nullif(trim(coalesce(p_reference_type, '')), ''),\n    nullif(trim(coalesce(p_reference_id, '')), ''),\n    nullif(trim(coalesce(p_idempotency_key, '')), ''),\n    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(\n      'overdrafted',\n      next_balance < 0,\n      'overdraftLimitCents',\n      overdraft_limit\n    )\n  )\n  returning * into inserted_ledger;\n\n  return query select true, next_balance, inserted_ledger.id, false;\nend;\n$function$\n","routine_kind":"f","routine_name":"consume_user_credits","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":3402,"full_arguments":"p_organization_id uuid, p_user_id uuid, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_plan_tier text, p_status text, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_metadata jsonb, p_stripe_event_id text, p_stripe_event_created bigint","identity_arguments":"p_organization_id uuid, p_user_id uuid, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_plan_tier text, p_status text, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_metadata jsonb, p_stripe_event_id text, p_stripe_event_created bigint","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"TABLE(applied boolean, ignored_reason text, latest_event_created bigint)","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.apply_billing_subscription_webhook(p_organization_id uuid, p_user_id uuid, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_price_id text, p_plan_tier text, p_status text, p_current_period_start timestamp with time zone, p_current_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_metadata jsonb, p_stripe_event_id text, p_stripe_event_created bigint)\n RETURNS TABLE(applied boolean, ignored_reason text, latest_event_created bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  normalized_event_created bigint := greatest(coalesce(p_stripe_event_created, 0), 0);\n  normalized_event_id text := coalesce(p_stripe_event_id, '');\n  stored_event_created bigint;\nbegin\n  if p_organization_id is null then\n    raise exception 'p_organization_id is required';\n  end if;\n\n  if p_stripe_subscription_id is null or length(trim(p_stripe_subscription_id)) = 0 then\n    raise exception 'p_stripe_subscription_id is required';\n  end if;\n\n  insert into public.billing_subscriptions (\n    organization_id,\n    user_id,\n    stripe_customer_id,\n    stripe_subscription_id,\n    stripe_price_id,\n    plan_tier,\n    status,\n    current_period_start,\n    current_period_end,\n    cancel_at_period_end,\n    metadata,\n    stripe_latest_event_id,\n    stripe_latest_event_created,\n    updated_at\n  )\n  values (\n    p_organization_id,\n    p_user_id,\n    p_stripe_customer_id,\n    p_stripe_subscription_id,\n    p_stripe_price_id,\n    coalesce(nullif(p_plan_tier, ''), 'starter'),\n    coalesce(nullif(p_status, ''), 'inactive'),\n    p_current_period_start,\n    p_current_period_end,\n    coalesce(p_cancel_at_period_end, false),\n    coalesce(p_metadata, '{}'::jsonb),\n    p_stripe_event_id,\n    normalized_event_created,\n    timezone('utc', now())\n  )\n  on conflict (organization_id) do update\n  set user_id = excluded.user_id,\n      stripe_customer_id = excluded.stripe_customer_id,\n      stripe_subscription_id = excluded.stripe_subscription_id,\n      stripe_price_id = excluded.stripe_price_id,\n      plan_tier = excluded.plan_tier,\n      status = excluded.status,\n      current_period_start = excluded.current_period_start,\n      current_period_end = excluded.current_period_end,\n      cancel_at_period_end = excluded.cancel_at_period_end,\n      metadata = excluded.metadata,\n      stripe_latest_event_id = excluded.stripe_latest_event_id,\n      stripe_latest_event_created = excluded.stripe_latest_event_created,\n      updated_at = timezone('utc', now())\n  where public.billing_subscriptions.stripe_latest_event_created < excluded.stripe_latest_event_created\n     or (\n       public.billing_subscriptions.stripe_latest_event_created = excluded.stripe_latest_event_created\n       and coalesce(public.billing_subscriptions.stripe_latest_event_id, '') < normalized_event_id\n     )\n  returning stripe_latest_event_created\n  into stored_event_created;\n\n  if stored_event_created is not null then\n    applied := true;\n    ignored_reason := null;\n    latest_event_created := stored_event_created;\n    return next;\n    return;\n  end if;\n\n  select stripe_latest_event_created\n  into stored_event_created\n  from public.billing_subscriptions\n  where organization_id = p_organization_id;\n\n  applied := false;\n  ignored_reason := 'stale_event';\n  latest_event_created := stored_event_created;\n  return next;\nend;\n$function$\n","routine_kind":"f","routine_name":"apply_billing_subscription_webhook","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":347,"full_arguments":"org_id uuid","identity_arguments":"org_id uuid","language_name":"sql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"boolean","returns_set":false,"routine_definition":"CREATE OR REPLACE FUNCTION public.is_org_member(org_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists (\n    select 1\n    from public.organization_memberships membership\n    where membership.organization_id = org_id\n      and membership.user_id = auth.uid()\n  );\n$function$\n","routine_kind":"f","routine_name":"is_org_member","routine_schema":"public","security_definer":true,"strict":false,"volatility":"s"},{"definition_bytes":433,"full_arguments":"p_partner_id uuid","identity_arguments":"p_partner_id uuid","language_name":"sql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"boolean","returns_set":false,"routine_definition":"CREATE OR REPLACE FUNCTION public.is_current_user_partner_member(p_partner_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists (\n    select 1\n    from public.partner_memberships membership_record\n    where membership_record.partner_id = p_partner_id\n      and membership_record.user_id = auth.uid()\n      and membership_record.status = 'active'\n  );\n$function$\n","routine_kind":"f","routine_name":"is_current_user_partner_member","routine_schema":"public","security_definer":true,"strict":false,"volatility":"s"},{"definition_bytes":440,"full_arguments":"p_older_than interval DEFAULT '24:00:00'::interval","identity_arguments":"p_older_than interval","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"integer","returns_set":false,"routine_definition":"CREATE OR REPLACE FUNCTION public.cleanup_expired_rate_limit_buckets(p_older_than interval DEFAULT '24:00:00'::interval)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  deleted_count integer;\nbegin\n  delete from public.rate_limit_buckets\n  where reset_at < timezone('utc', now()) - p_older_than;\n\n  get diagnostics deleted_count = row_count;\n  return deleted_count;\nend;\n$function$\n","routine_kind":"f","routine_name":"cleanup_expired_rate_limit_buckets","routine_schema":"public","security_definer":true,"strict":false,"volatility":"v"},{"definition_bytes":4703,"full_arguments":"p_organization_id uuid, p_user_id uuid, p_campaign_id uuid, p_provider text, p_operation text, p_limit_count integer, p_idempotency_key text DEFAULT NULL::text, p_estimated_cost numeric DEFAULT NULL::numeric","identity_arguments":"p_organization_id uuid, p_user_id uuid, p_campaign_id uuid, p_provider text, p_operation text, p_limit_count integer, p_idempotency_key text, p_estimated_cost numeric","language_name":"plpgsql","leakproof":false,"owner_name":"postgres","parallel_mode":"u","return_clause":"TABLE(allowed boolean, current_count integer, next_count integer, limit_count integer, usage_id uuid, event_id uuid, reused_existing boolean, event_status text)","returns_set":true,"routine_definition":"CREATE OR REPLACE FUNCTION public.reserve_provider_usage(p_organization_id uuid, p_user_id uuid, p_campaign_id uuid, p_provider text, p_operation text, p_limit_count integer, p_idempotency_key text DEFAULT NULL::text, p_estimated_cost numeric DEFAULT NULL::numeric)\n RETURNS TABLE(allowed boolean, current_count integer, next_count integer, limit_count integer, usage_id uuid, event_id uuid, reused_existing boolean, event_status text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  today date := current_date;\n  usage_row public.provider_usage_limits%rowtype;\n  existing_event public.provider_usage_events%rowtype;\n  new_event public.provider_usage_events%rowtype;\nbegin\n  if p_user_id is null then\n    raise exception 'p_user_id is required';\n  end if;\n\n  if p_limit_count <= 0 then\n    raise exception 'p_limit_count must be positive';\n  end if;\n\n  if p_idempotency_key is not null then\n    select *\n    into existing_event\n    from public.provider_usage_events\n    where idempotency_key = p_idempotency_key\n      and organization_id = p_organization_id\n      and user_id = p_user_id\n      and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =\n          coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)\n      and provider = p_provider\n      and operation = p_operation\n      and usage_date = today\n    limit 1;\n\n    if existing_event.id is not null then\n      select *\n      into usage_row\n      from public.provider_usage_limits\n      where user_id = existing_event.user_id\n        and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =\n            coalesce(existing_event.campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)\n        and provider = existing_event.provider\n        and operation = existing_event.operation\n        and usage_date = existing_event.usage_date;\n\n      allowed := true;\n      current_count := greatest(coalesce(usage_row.usage_count, 1) - 1, 0);\n      next_count := coalesce(usage_row.usage_count, 1);\n      limit_count := coalesce(usage_row.limit_count, p_limit_count);\n      usage_id := usage_row.id;\n      event_id := existing_event.id;\n      reused_existing := true;\n      event_status := existing_event.status;\n      return next;\n      return;\n    end if;\n  end if;\n\n  begin\n    insert into public.provider_usage_limits (\n      organization_id,\n      user_id,\n      campaign_id,\n      provider,\n      operation,\n      usage_date,\n      usage_count,\n      limit_count\n    )\n    values (\n      p_organization_id,\n      p_user_id,\n      p_campaign_id,\n      p_provider,\n      p_operation,\n      today,\n      0,\n      p_limit_count\n    );\n  exception when unique_violation then\n    update public.provider_usage_limits\n    set limit_count = p_limit_count,\n        updated_at = now()\n    where user_id = p_user_id\n      and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =\n          coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)\n      and provider = p_provider\n      and operation = p_operation\n      and usage_date = today;\n  end;\n\n  select *\n  into usage_row\n  from public.provider_usage_limits\n  where user_id = p_user_id\n    and coalesce(campaign_id, '00000000-0000-0000-0000-000000000000'::uuid) =\n        coalesce(p_campaign_id, '00000000-0000-0000-0000-000000000000'::uuid)\n    and provider = p_provider\n    and operation = p_operation\n    and usage_date = today\n  for update;\n\n  if usage_row.usage_count >= p_limit_count then\n    allowed := false;\n    current_count := usage_row.usage_count;\n    next_count := usage_row.usage_count;\n    limit_count := p_limit_count;\n    usage_id := usage_row.id