  actual jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(to_jsonb(actual_row) ORDER BY to_jsonb(actual_row)::text), '[]'::jsonb) INTO actual
  FROM (SELECT "object_kind", "schema_name", "object_name", "routine_identity_arguments", "owner_name", "explicit_acl_was_null", "grantor_name", "grantee_name", "privilege_type", "is_grantable" FROM (SELECT
  'sequence' AS object_kind,
  n.nspname AS schema_name,
  c.relname AS object_name,
  NULL AS routine_identity_arguments,
  pg_catalog.pg_get_userbyid(c.relowner) AS owner_name,
  c.relacl IS NULL AS explicit_acl_was_null,
  pg_catalog.pg_get_userbyid(acl.grantor) AS grantor_name,
  CASE WHEN acl.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END AS grantee_name,
  acl.privilege_type AS privilege_type,
  acl.is_grantable AS is_grantable
FROM pg_catalog.pg_class AS c
JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(c.relacl, pg_catalog.acldefault('s', c.relowner))) AS acl
WHERE n.nspname IN ('public', 'storage', 'auth', 'extensions', 'graphql_public', 'supabase_migrations')
  AND c.relkind = 'S'
ORDER BY n.nspname, c.relname, acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable) AS source_row WHERE source_row."schema_name" = 'public') AS actual_row;
  IF EXISTS (
    (SELECT value FROM jsonb_array_elements(expected) EXCEPT ALL SELECT value FROM jsonb_array_elements(actual))
    UNION ALL
    (SELECT value FROM jsonb_array_elements(actual) EXCEPT ALL SELECT value FROM jsonb_array_elements(expected))
  ) THEN
    RAISE EXCEPTION 'pre-candidate structural mismatch: public.13c_sequence_grants' USING ERRCODE='55000';
