  actual jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(to_jsonb(actual_row) ORDER BY to_jsonb(actual_row)::text), '[]'::jsonb) INTO actual
  FROM (SELECT "explicit_acl_was_null", "grantee_name", "grantor_name", "is_grantable", "object_kind", "object_name", "owner_name", "privilege_type", "routine_identity_arguments", "schema_name" FROM (SELECT
  'default_acl' AS object_kind,
  n.nspname AS schema_name,
  d.defaclobjtype AS object_name,
  NULL AS routine_identity_arguments,
  pg_catalog.pg_get_userbyid(d.defaclrole) AS owner_name,
  false AS explicit_acl_was_null,
  pg_catalog.pg_get_userbyid(acl.grantor) AS grantor_name,
  CASE WHEN acl.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(acl.grantee) END AS grantee_name,
  acl.privilege_type AS privilege_type,
  acl.is_grantable AS is_grantable
FROM pg_catalog.pg_default_acl AS d
LEFT JOIN pg_catalog.pg_namespace AS n ON n.oid = d.defaclnamespace
CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) AS acl
WHERE d.defaclnamespace = 0 OR n.nspname IN ('public', 'storage', 'auth', 'extensions', 'graphql_public', 'supabase_migrations')
ORDER BY n.nspname NULLS FIRST, d.defaclrole, d.defaclobjtype, acl.grantor, acl.grantee, acl.privilege_type, acl.is_grantable) AS source_row WHERE source_row."schema_name" = 'public') AS actual_row;
  IF EXISTS (
    (SELECT value FROM jsonb_array_elements(expected) EXCEPT ALL SELECT value FROM jsonb_array_elements(actual))
    UNION ALL
    (SELECT value FROM jsonb_array_elements(actual) EXCEPT ALL SELECT value FROM jsonb_array_elements(expected))
  ) THEN
    RAISE EXCEPTION 'pre-candidate structural mismatch: public.13e_default_grants' USING ERRCODE='55000';
  END IF;
END
$dealflow_catalog_gate_22$;

-- dealflow:gate-group private.01_schemas.schemas_and_acls
DO $dealflow_catalog_gate_23$
DECLARE
  expected jsonb := $dealflow_expected_23$[{"acl_uses_hardwired_default":false,"owner_name":"postgres","schema_name":"private"}]$dealflow_expected_23$::jsonb;
  actual jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(to_jsonb(actual_row) ORDER BY to_jsonb(actual_row)::text), '[]'::jsonb) INTO actual
  FROM (SELECT "schema_name", "owner_name", "acl_uses_hardwired_default" FROM (SELECT
  n.nspname AS schema_name,
  pg_catalog.pg_get_userbyid(n.nspowner) AS owner_name,
  n.nspacl IS NULL AS acl_uses_hardwired_default
FROM pg_catalog.pg_namespace AS n
WHERE n.nspname IN ('private')
ORDER BY n.nspname) AS source_row) AS actual_row;
  IF EXISTS (
    (SELECT value FROM jsonb_array_elements(expected) EXCEPT ALL SELECT value FROM jsonb_array_elements(actual))
    UNION ALL
    (SELECT value FROM jsonb_array_elements(actual) EXCEPT ALL SELECT value FROM jsonb_array_elements(expected))
  ) THEN
    RAISE EXCEPTION 'pre-candidate structural mismatch: private.01_schemas' USING ERRCODE='55000';
  END IF;
END
$dealflow_catalog_gate_23$;

-- dealflow:gate-group private.01b_private_object_class_inventory.fail_closed_private_object_class_inventory
DO $dealflow_catalog_gate_24$
