x_definition":"CREATE UNIQUE INDEX workspace_ghl_users_pkey ON public.workspace_ghl_users USING btree (id)","valid":true},{"table_name":"workspace_ghl_users","index_name":"workspace_ghl_users_workspace_partner_email_unique","index_definition":"CREATE UNIQUE INDEX workspace_ghl_users_workspace_partner_email_unique ON public.workspace_ghl_users USING btree (workspace_id, partner_id, email)","valid":true},{"table_name":"workspace_partner_attribution","index_name":"workspace_partner_attribution_pkey","index_definition":"CREATE UNIQUE INDEX workspace_partner_attribution_pkey ON public.workspace_partner_attribution USING btree (id)","valid":true},{"table_name":"workspace_partner_attribution","index_name":"workspace_partner_attribution_workspace_partner_idx","index_definition":"CREATE INDEX workspace_partner_attribution_workspace_partner_idx ON public.workspace_partner_attribution USING btree (workspace_id, partner_id)","valid":true},{"table_name":"workspace_partner_attribution","index_name":"workspace_partner_attribution_workspace_unique","index_definition":"CREATE UNIQUE INDEX workspace_partner_attribution_workspace_unique ON public.workspace_partner_attribution USING btree (workspace_id)","valid":true}]$dealflow_indexes$::jsonb) AS x(table_name text, index_name text, index_definition text, valid boolean)),
  actual AS (SELECT tc.relname, ic.relname, pg_catalog.pg_get_indexdef(i.indexrelid,0,false), i.indisvalid FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid JOIN pg_catalog.pg_class tc ON tc.oid=i.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=tc.relnamespace WHERE n.nspname='public')
  SELECT detail INTO mismatch FROM ((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) d, LATERAL (SELECT row_to_json(d)::text AS detail) j LIMIT 1;
  IF mismatch IS NOT NULL THEN RAISE EXCEPTION 'pre-candidate index mismatch: %', mismatch USING ERRCODE='55000'; END IF;
  IF EXISTS (SELECT 1 FROM public.campaign_plans WHERE user_id IS NOT NULL AND user_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') THEN
    RAISE EXCEPTION 'pre-candidate gate: campaign_plans.user_id contains non-canonical UUID text' USING ERRCODE='22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.campaign_plans WHERE user_id IS NOT NULL AND user_id <> (user_id::uuid)::text) THEN
    RAISE EXCEPTION 'pre-candidate gate: campaign_plans.user_id is not canonical lowercase UUID text' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.leads lead_record
    WHERE lead_record.campaign_id IS NOT NULL AND lead_record.organization_id IS NOT NULL AND lead_record.user_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.campaign_plans campaign_record WHERE campaign_record.id=lead_record.campaign_id
        AND campaign_record.organization_id=lead_record.organization_id AND campaign_record.user_id=lead_record.user_id::text)
  ) THEN RAISE EXCEPTION 'pre-candidate gate: lead campaign tenant relationship mismatch' USING ERRCODE='23503'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.creative_assets asset_record
    WHERE asset_record.campaign_id IS NOT NULL AND asset_record.user_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.campaign_plans campaign_record WHERE campaign_record.id=asset_record.campaign_id
        AND campaign_record.user_id=asset_record.user_id::text)
  ) THEN RAISE EXCEPTION 'pre-candidate gate: creative asset campaign tenant relationship mismatch' USING ERRCODE='23503'; END IF;
END
$dealflow_pre_candidate_gate$;

DROP POLICY "campaign_plans_member_access" ON "public"."campaign_plans";
DROP POLICY "creative_assets_member_access" ON "public"."creative_assets";
DROP POLICY "meta_launch_locks_member_select" ON "public"."meta_launch_locks";

ALTER TABLE public.campaign_plans ALTER COLUMN user_id TYPE uuid USING user_id::uuid;

CREATE POLICY "campaign_plans_member_access" ON "public"."campaign_plans"
  AS PERMISSIVE
  FOR ALL
  TO "authenticated"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR (owner_id = (( SELECT auth.uid() AS uid))::text) OR private.is_current_user_org_member(organization_id)))
  WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) OR (owner_id = (( SELECT auth.uid() AS uid))::text) OR private.is_current_user_org_member(organization_id)));

CREATE POLICY "creative_assets_member_access" ON "public"."creative_assets"
  AS PERMISSIVE
  FOR ALL
  TO "authenticated"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM campaign_plans campaign_record
  WHERE ((campaign_record.id = creative_assets.campaign_id) AND ((campaign_record.user_id = ( SELECT auth.uid() AS uid)) OR (campaign_record.owner_id = (( SELECT auth.uid() AS uid))::text) OR private.is_current_user_org_member(campaign_record.organization_id)))))))
  WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM campaign_plans campaign_record
  WHERE ((campaign_record.id = creative_assets.campaign_id) AND ((campaign_record.user_id = ( SELECT auth.uid() AS uid)) OR (campaign_record.owner_id = (( SELECT auth.uid() AS uid))::text) OR private.is_current_user_org_member(campaign_record.organization_id)))))));

CREATE POLICY "meta_launch_locks_member_select" ON "public"."meta_launch_locks"
  AS PERMISSIVE
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM campaign_plans campaign_record
  WHERE ((campaign_record.id = meta_launch_locks.campaign_id) AND ((campaign_record.user_id = ( SELECT auth.uid() AS uid)) OR (campaign_record.owner_id = (( SELECT auth.uid() AS uid))::text) OR private.is_current_user_org_member(campaign_record.organization_id))))));

DO $dealflow_pre_candidate_postcondition$
BEGIN
  IF (SELECT pg_catalog.format_type(a.atttypid,a.atttypmod) FROM pg_catalog.pg_attribute a WHERE a.attrelid='public.campaign_plans'::regclass AND a.attname='user_id' AND NOT a.attisdropped) <> 'uuid' THEN
    RAISE EXCEPTION 'pre-candidate postcondition: campaign_plans.user_id is not uuid' USING ERRCODE='55000';
  END IF;
  IF (SELECT pg_catalog.format_type(a.atttypid,a.atttypmod) FROM pg_catalog.pg_attribute a WHERE a.attrelid='public.campaign_plans'::regclass AND a.attname='owner_id' AND NOT a.attisdropped) <> 'text' THEN
    RAISE EXCEPTION 'pre-candidate postcondition: campaign_plans.owner_id drifted' USING ERRCODE='55000';
  END IF;
  IF (SELECT count(*) FROM pg_catalog.pg_policy policy_record JOIN pg_catalog.pg_class relation_record ON relation_record.oid=policy_record.polrelid
      JOIN pg_catalog.pg_namespace namespace_record ON namespace_record.oid=relation_record.relnamespace
      WHERE namespace_record.nspname='public' AND (relation_record.relname, policy_record.polname) IN (
        ('campaign_plans','campaign_plans_member_access'),('creative_assets','creative_assets_member_access'),('meta_launch_locks','meta_launch_locks_member_select'))) <> 3 THEN
    RAISE EXCEPTION 'pre-candidate postcondition: dependent policies were not restored' USING ERRCODE='55000';
  END IF;
END
$dealflow_pre_candidate_postcondition$;

COMMIT;
